// keeps a terminal run from being revived: a failed or succeeded generation
// must not accept a late binding and re-enter the queue.
func (q *Queries) SetGoalPlanGenerationRun(ctx context.Context, arg SetGoalPlanGenerationRunParams) (GoalPlanGeneration, error) {
	row := q.db.QueryRow(ctx, setGoalPlanGenerationRun,
		arg.ChatSessionID,
		arg.TaskID,
		arg.ID,
		arg.WorkspaceID,
	)
	var i GoalPlanGeneration
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.GoalID,
		&i.ProjectID,
		&i.RequestKey,
		&i.Intent,
		&i.AgentID,
		&i.BaseRevision,
		&i.State,
		&i.ChatSessionID,
		&i.TaskID,
		&i.InputContext,
		&i.Candidate,
		&i.Applied,
		&i.AppliedRevision,
		&i.ObservedRevision,
		&i.Error,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const updateGoalPlanContent = `-- name: UpdateGoalPlanContent :one
UPDATE goal_plan SET
    content = $1::jsonb,
    context_snapshot = $2::jsonb,
    revision = revision + 1,
    updated_at = now()
WHERE workspace_id = $3
  AND goal_id = $4
  AND revision = $5
RETURNING id, workspace_id, goal_id, project_id, revision, state, content, context_snapshot, created_at, updated_at
`

type UpdateGoalPlanContentParams struct {
	Content          []byte      `json:"content"`
	ContextSnapshot  []byte      `json:"context_snapshot"`
	WorkspaceID      pgtype.UUID `json:"workspace_id"`
	GoalID           pgtype.UUID `json:"goal_id"`
	ExpectedRevision int32       `json:"expected_revision"`
}

// Compare-and-swap on the revision: no row means the caller edited a stale
// draft, and the handler answers 409 instead of overwriting newer input.
func (q *Queries) UpdateGoalPlanContent(ctx context.Context, arg UpdateGoalPlanContentParams) (GoalPlan, error) {
	row := q.db.QueryRow(ctx, updateGoalPlanContent,
		arg.Content,
		arg.ContextSnapshot,
		arg.WorkspaceID,
		arg.GoalID,
		arg.ExpectedRevision,
	)
	var i GoalPlan
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.GoalID,
		&i.ProjectID,
		&i.Revision,
		&i.State,
		&i.Content,
		&i.ContextSnapshot,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
